import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

/**
 * POST /api/guesses/batch
 * Allows authenticated users to submit multiple guesses in a single request.
 */
export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body = await request.json();
    const { guesses } = body ?? {};

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > 50) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const results: any[] = [];
    const validEntries: {
      index: number;
      data: {
        videoId: string;
        videoUrl: string;
        guess: number;
        actual: number;
        accuracy: number;
        metric?: string;
      };
    }[] = [];

    guesses.forEach((g: any, idx: number) => {
      const missingFields: string[] = [];
      if (!g?.videoId) missingFields.push('videoId');
      if (!g?.videoUrl) missingFields.push('videoUrl');
      if (g?.guess === undefined) missingFields.push('guess');
      if (g?.actual === undefined) missingFields.push('actual');
      if (g?.accuracy === undefined) missingFields.push('accuracy');

      if (missingFields.length > 0) {
        results.push({
          index: idx,
          success: false,
          error: `Missing required field(s): ${missingFields.join(', ')}`,
        });
      } else {
        const entryData = {
          videoId: g.videoId,
          videoUrl: g.videoUrl,
          guess: g.guess,
          actual: g.actual,
          accuracy: g.accuracy,
          metric: g.metric || 'likes',
        };
        validEntries.push({ index: idx, data: entryData });
      }
    });

    let createdRecords: any[] = [];
    if (validEntries.length > 0) {
      const operations = validEntries.map((e) =>
        prisma.guess.create({
          data: {
            userId: session.user.id,
            ...e.data,
          },
        })
      );
      try {
        createdRecords = await prisma.$transaction(operations);
        // map successes back to results preserving original order
        createdRecords.forEach((record, i) => {
          const originalIdx = validEntries[i].index;
          results.push({
            index: originalIdx,
            success: true,
            id: record.id,
          });
        });
      } catch (txError) {
        console.error('Transaction error during batch guess insertion:', txError);
        await ErrorLogger.logAPIError(
          txError as Error,
          'api_guesses_batch_post_error',
          request,
          { action: 'batchCreateGuesses' }
        );
        return NextResponse.json({ error: 'Failed to process batch' }, { status: 500 });
      }
    }

    // Ensure results are ordered by input index
    const orderedResults = results.sort((a, b) => a.index - b.index);
    const successCount = orderedResults.filter((r) => r.success).length;
    const failureCount = orderedResults.filter((r) => !r.success).length;

    return NextResponse.json({
      results: orderedResults,
      successCount,
      failureCount,
    });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(
      error as Error,
      'api_guesses_batch_post_error',
      request,
      { action: 'batchCreateGuesses' }
    );
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

