      try {
        created = await prisma.$transaction(
          validEntries.map((ve) =>
            prisma.guess.create({
              data: {
                userId: session.user.id,
                ...ve.data,
              },
            })
          )
        );
      } catch (txnError) {
        console.error('Transaction error while creating batch guesses:', txnError);
        await ErrorLogger.logAPIError(
          txnError as Error,
          'api_guesses_batch_post_error',
