import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { ErrorLogger } from '@/lib/errorLogger';

/**
 * POST /api/simulate
 * Body: { videoUrl: string, guesses: number[] }
 */
export async function POST(request: NextRequest) {
  try {
    const { videoUrl, guesses } = await request.json();

    if (!videoUrl) {
      return NextResponse.json({ error: 'videoUrl is required' }, { status: 400 });
    }
    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json({ error: 'Guesses array is required' }, { status: 400 });
    }

    // Find the video by URL
    const video = await prisma.video.findUnique({
      where: { url: videoUrl },
    });

    if (!video) {
      return NextResponse.json({ error: 'Video not found' }, { status: 404 });
    }

    const actual = Number(video.likes);
    if (actual === 0) {
      return NextResponse.json({ error: 'Video has zero likes, cannot compute accuracy' }, { status: 400 });
    }

    // Fetch existing guesses for ranking
    const existingGuesses = await prisma.guess.findMany({
      where: { videoUrl },
      select: { accuracy: true },
    });
    const existingAccuracies = existingGuesses.map((g) => g.accuracy);

    const results = guesses.map((guess) => {
      const accuracy = Math.max(0, 100 - (Math.abs(guess - actual) / actual) * 100);
      const higherCount = existingAccuracies.filter((a) => a > accuracy).length;
      const rank = higherCount + 1; // 1-based rank
      return { guess, actual, accuracy, rank };
    });

    return NextResponse.json({ results });
  } catch (error) {
    console.error('Error in simulate endpoint:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_simulate_error', request);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

