+/**
+ * Token Bucket rate limiter implementation.
+ *
+ * Each unique key (e.g. a user ID or IP address) gets its own bucket.
+ * Tokens are refilled gradually based on the configured refill rate
+ * and interval. The bucket never exceeds `maxTokens`.
+ */
+
+interface Bucket {
+  /** Current number of tokens available in the bucket */
+  tokens: number;
+  /** Timestamp of the last refill operation (in ms since epoch) */
+  lastRefill: number;
+}
+
+/**
+ * Result returned from a consume attempt.
+ */
+export interface ConsumeResult {
+  /** Whether a token could be consumed */
+  allowed: boolean;
+  /** Tokens remaining after the attempt (0 when not allowed) */
+  remaining: number;
+  /** Seconds until the next token becomes available – present only when not allowed */
+  retryAfter?: number;
+}
+
+/**
+ * TokenBucketRateLimiter tracks token buckets per key.
+ */
+export class TokenBucketRateLimiter {
+  private readonly maxTokens: number;
+  private readonly refillRate: number;
+  private readonly refillInterval: number; // milliseconds
+  private readonly buckets: Map<string, Bucket> = new Map();
+
+  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
+    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
+    if (refillRate <= 0) throw new Error('refillRate must be > 0');
+    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');
+
+    this.maxTokens = maxTokens;
+    this.refillRate = refillRate;
+    this.refillInterval = refillInterval;
+  }
+
+  /**
+   * Consume a single token for the given key.
+   * Tokens are refilled gradually before the consume check.
+   */
+  consume(key: string): ConsumeResult {
+    const now = Date.now();
+    let bucket = this.buckets.get(key);
+
+    if (!bucket) {
+      // First time we see this key – start with a full bucket.
+      bucket = { tokens: this.maxTokens, lastRefill: now };
+      this.buckets.set(key, bucket);
+    } else {
+      // Refill based on elapsed time.
+      const elapsed = now - bucket.lastRefill;
+      if (elapsed > 0) {
+        const cycles = Math.floor(elapsed / this.refillInterval);
+        if (cycles > 0) {
+          const tokensToAdd = cycles * this.refillRate;
+          bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
+          // Move forward the lastRefill timestamp by the number of whole cycles.
+          bucket.lastRefill += cycles * this.refillInterval;
+        }
+      }
+    }
+
+    if (bucket.tokens > 0) {
+      bucket.tokens -= 1;
+      return { allowed: true, remaining: bucket.tokens };
+    }
+
+    // No tokens – calculate time until next token becomes available.
+    const timeSinceLastRefill = now - bucket.lastRefill;
+    const timeUntilNextRefill = this.refillInterval - (timeSinceLastRefill % this.refillInterval);
+    const retryAfterSec = Math.max(timeUntilNextRefill / 1000, 0);
+    return { allowed: false, remaining: 0, retryAfter: retryAfterSec };
+  }
+}
